PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS branches (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_branches (user_id INTEGER REFERENCES users(id), branch_id INTEGER REFERENCES branches(id), PRIMARY KEY(user_id, branch_id));
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, contact TEXT NOT NULL DEFAULT '', items TEXT NOT NULL DEFAULT '', terms TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents >= 0), supplier_id INTEGER REFERENCES suppliers(id));
CREATE TABLE IF NOT EXISTS inventory (branch_id INTEGER REFERENCES branches(id), product_id INTEGER REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity >= 0), reorder_level INTEGER NOT NULL CHECK(reorder_level >= 0), PRIMARY KEY(branch_id, product_id));
CREATE TABLE IF NOT EXISTS sales (id INTEGER PRIMARY KEY, receipt TEXT UNIQUE, client_key TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL REFERENCES branches(id), user_id INTEGER NOT NULL REFERENCES users(id), total_cents INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sale_items (id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), product_id INTEGER NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), price_cents INTEGER NOT NULL, returned_quantity INTEGER NOT NULL DEFAULT 0 CHECK(returned_quantity >= 0 AND returned_quantity <= quantity));
CREATE TABLE IF NOT EXISTS returns (id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), user_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('refund','defective')), amount_cents INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_orders (id INTEGER PRIMARY KEY, branch_id INTEGER NOT NULL REFERENCES branches(id), supplier_id INTEGER NOT NULL REFERENCES suppliers(id), created_by INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','received')), approved_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_items (order_id INTEGER REFERENCES purchase_orders(id), product_id INTEGER REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), received_quantity INTEGER NOT NULL DEFAULT 0 CHECK(received_quantity >= 0 AND received_quantity <= quantity), PRIMARY KEY(order_id, product_id));
CREATE TABLE IF NOT EXISTS deliveries (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES purchase_orders(id), product_id INTEGER NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), damaged_quantity INTEGER NOT NULL CHECK(damaged_quantity >= 0 AND damaged_quantity <= quantity), received_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS employees (id INTEGER PRIMARY KEY, name TEXT NOT NULL, branch_id INTEGER NOT NULL REFERENCES branches(id), daily_rate_cents INTEGER NOT NULL CHECK(daily_rate_cents >= 0));
CREATE TABLE IF NOT EXISTS attendance (id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), work_date TEXT NOT NULL, time_in TEXT NOT NULL, time_out TEXT, source TEXT NOT NULL DEFAULT 'simulated-fingerprint', recorded_by INTEGER NOT NULL REFERENCES users(id), UNIQUE(employee_id, work_date));
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL);
